type ActivityCopy={planning:string;acting:string;checking:string;result:string};
function plpActivityCopy(message:string,ctx:any):ActivityCopy|null{
  const selected=rec(ctx?.selectedObject),route=txt(ctx?.route).toLowerCase(),workspace=txt(selected.workspaceSlug).toLowerCase();
  if(!(route.includes("/plp-boracay/")||workspace==="plp-boracay"))return null;
  const m=message.toLowerCase();
  if(/\b(booking|reservation|arrival|departure|occupancy|room|availability|check[- ]?in|check[- ]?out)\b/.test(m))return{
    planning:"Preparing the booking and room-status check.",
    acting:"Checking bookings, arrivals, departures, and room availability.",
    checking:"Verifying booking and occupancy details.",
    result:"Booking and occupancy check complete."
  };
  if(/\b(guest|vip|in[- ]house|stay|guest request|special request)\b/.test(m))return{
    planning:"Preparing the guest-status check.",
    acting:"Checking guest stays and open guest requests.",
    checking:"Verifying the guest details used for this answer.",
    result:"Guest-status check complete."
  };
  if(/\b(revenue|sales|income|payment|unpaid|finance|booking performance)\b/.test(m))return{
    planning:"Preparing the resort performance check.",
    acting:"Checking revenue, payments, and booking performance.",
    checking:"Verifying the financial and booking figures.",
    result:"Performance check complete."
  };
  if(/\b(task|staff|issue|operation|maintenance|housekeeping|attention|conflict)\b/.test(m))return{
    planning:"Preparing the operations check.",
    acting:"Checking open operational tasks, staff work, and issues.",
    checking:"Verifying the operational status.",
    result:"Operations check complete."
  };
  return{
    planning:"Preparing the resort check.",
    acting:"Checking the current resort operating snapshot.",
    checking:"Verifying the resort details used for this answer.",
    result:"Resort check complete."
  };
}
function activityCopy(message:string,ctx:any,phase:keyof ActivityCopy){
  const plp=plpActivityCopy(message,ctx);
  if(plp)return plp[phase];
  return phase==="planning"?"Preparing the requested work.":phase==="acting"?"Working through the requested information.":phase==="checking"?"Verifying the result.":"Done.";
}
function capabilityCopy(result:any,phase:"checking"|"result"){
  const row=rec(result),readback=rec(row.providerReadback),cap=txt(readback.capability,txt(row.intent)).toLowerCase();
  const done=phase==="result";
  if(cap.includes("staff_task")||cap.includes("task.create"))return done?"Staff task created and verified.":"Verifying the new staff task.";
  if(cap.includes("calendar"))return done?"Calendar change completed and verified.":"Verifying the calendar change.";
  if(cap.includes("email")||cap.includes("message")||cap.includes("communication"))return done?"Communication completed and verified.":"Verifying the communication.";
  if(cap.includes("guest"))return done?"Guest record action completed and verified.":"Verifying the guest record.";
  if(cap.includes("booking")||cap.includes("reservation"))return done?"Booking action completed and verified.":"Verifying the booking action.";
  if(cap.includes("github")||cap.includes("code")||cap.includes("repository"))return done?"Requested system change completed and verified.":"Verifying the requested system change.";
  return done?"Requested action completed and verified.":"Verifying the requested action.";
}
